tool_calls.arguments:
{"command": "cd /tmp && kubectl get deploy app -n default -o json > deploy_before.json && cat > patch.json <<'EOF'
{
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {
            "name": "app",
            "livenessProbe": {
              "httpGet": {"path": "/", "port": 80, "scheme": "HTTP"},
              "periodSeconds": 10,
              "failureThreshold": 3,
              "successThreshold": 1,
              "timeoutSeconds": 1
            },
            "startupProbe": {
              "httpGet": {"path": "/", "port": 80, "scheme": "HTTP"},
              "periodSeconds": 2,
              "failureThreshold": 15,
              "successThreshold": 1,
              "timeoutSeconds": 1
            }
          }
        ]
      }
    }
  }
}
EOF
kubectl patch deploy app -n default --type=strategic -p "$(cat patch.json)""}

